import * as core from './assets/iso-kit.mjs';
const k={...core};for(const type of ['slabOf','cylinder','extrude']){k[type]=(...args)=>{const paths=core[type](...args);paths.geometry={type,args};return paths;};}
export const BASE={x:-145,y:-74,w:290,d:148,r:10};
export const P=k.fitProjection([...k.boxCorners(BASE,-15,0),[-76,0,70],[76,0,70]],640,330,{pad:44,azimuth:38,elevation:37});
export function gearRing(x,r,n){return Array.from({length:n*4},(_,i)=>{const a=i/(n*4)*Math.PI*2,rr=r+(i%4===1||i%4===2?1.2:-1.2);return [x+Math.cos(a)*rr,Math.sin(a)*rr]})}
export function chainPath(rear=21){const r1=46,r2=rear/21*22+2,dist=152,a=Math.acos((r1-r2)/dist),pts=[];for(let i=0;i<=36;i++){let q=a+(2*Math.PI-2*a)*i/36;pts.push([-76+Math.cos(q)*r1,Math.sin(q)*r1])}for(let i=0;i<=24;i++){let q=-a+2*a*i/24;pts.push([76+Math.cos(q)*r2,Math.sin(q)*r2])}return pts}
export function makeFigure(record){const out=[],S=(p,t='mid')=>{const svg=k.solidSvg(p,{tone:t});if(record)record(p.geometry,svg);return svg;},L=(d,t='lo')=>k.lineSvg(d,{tone:t});
for(const [x,y] of k.corners(BASE,18))out.push(S(k.cylinder(x,y,7,-15,5,P,24),'lo'));
out.push(S(k.slabOf(BASE,-10,10,P,8,1.2),'lo'),L(k.planOutline(k.insetPlan(BASE,5),0,P),'faint'));
for(const [x,y]of k.corners(BASE,11))out.push(L(k.ring(x,y,2,0,P,16)),k.dotsSvg([k.iso([x,y,0],P)],{size:.6}));
for(const y of [-52,48]){const rail={x:-122,y,w:244,d:5,r:1};out.push(S(k.slabOf(rail,0,3,P,4)));for(const x of [-115,115])out.push(k.dotsSvg([k.iso([x,y+2.5,3],P)],{size:.7}));}
for(const x of [-76,76]){out.push(S(k.slabOf({x:x-20,y:-21,w:40,d:42,r:4},0,8,P,5,.7)));for(const dx of [-14,14])for(const y of [-15,15])out.push(S(k.cylinder(x+dx,y,2.1,8,1.5,P,16),'hi'));out.push(S(k.cylinder(x,0,13,8,9,P,32)),S(k.cylinder(x,0,7,17,27,P,32),'hi'),L(k.sideArc(x,0,7,23,P,24)));}
out.push(`<g id="front-gear">${S(k.extrude(gearRing(-76,44,42),44,3,P,{convex:false,bevel:.4}),'hi')}</g><g id="rear-gear">${S(k.extrude(gearRing(76,22,21),44,3,P,{convex:false,bevel:.4}),'hi')}</g>`);
for(const [x,r]of [[-76,44],[76,22]]){let pattern='';for(let i=0;i<5;i++){const a=i*Math.PI*2/5;pattern+=`<circle cx="${Math.cos(a)*r*.6}" cy="${Math.sin(a)*r*.6}" r="${r*.16}" fill="#333d2b" stroke="#8b987e" stroke-width=".45"/>`}out.push(`<g transform="${k.topMatrix([x,0],47.1,P)}"><g id="${x<0?'front':'rear'}-spin">${pattern}</g></g>`)}
out.push(`<g transform="${k.topMatrix([0,0],47.2,P)}" id="chain-links">${Array.from({length:84},()=>'<g class="chain-link"><rect x="-3.4" y="-1.35" width="6.8" height="2.7" rx="1.35" fill="#b5bf9f" stroke="#303829" stroke-width=".65"/><circle cx="-2" r=".55" fill="#3c4730"/><circle cx="2" r=".55" fill="#3c4730"/></g>').join('')}</g>`);
for(const x of [-76,76]){out.push(S(k.cylinder(x,0,6,47,4,P,24),'hi'),L(k.ring(x,0,3.4,51,P,24),'lo'),k.dotsSvg([k.iso([x,0,51],P)],{size:.8,tone:'hi'}))}
out.push(`<g transform="${k.topMatrix([-76,0],51.5,P)}"><g id="crank-spin"><rect x="-4" y="-4" width="38" height="8" rx="3" fill="#d7f749" stroke="#313f24" stroke-width=".8"/><rect x="29" y="-10" width="16" height="20" rx="2" fill="#5c6850" stroke="#cbd9b4" stroke-width=".8"/>${[-6,0,6].map(y=>`<path d="M31 ${y}h12" stroke="#a8b49b" stroke-width="1"/>`).join('')}<circle r="2" fill="#293521"/></g></g>`);
const strip={x:-100,y:57,w:200,d:6,r:.8};out.push(S(k.slabOf(strip,0,.5,P,3),'mid'));const ticks=k.topTicks(-96,96,4,5,57,.5,[2,4],P);out.push(L(ticks.minor),L(ticks.major,'hi'));
return k.figureSvg({width:640,height:330,label:'An isometric benchtop bicycle drivetrain: a large chainring drives a smaller rear sprocket with a continuous chain. The crank and sprocket rotate in proportion to the selected gear ratio.',body:out});}
export function mount(){document.querySelector('#anatomy').innerHTML=makeFigure();let rpm=60,rear=21,angle=0,last=0,visible=false,paused=false,frame=0;const reduced=matchMedia('(prefers-reduced-motion: reduce)'),links=[...document.querySelectorAll('.chain-link')];let path,lengths,total;
function route(){path=chainPath(rear);lengths=[0];for(let i=0;i<path.length;i++){const a=path[i],b=path[(i+1)%path.length];lengths.push(lengths.at(-1)+Math.hypot(b[0]-a[0],b[1]-a[1]))}total=lengths.at(-1)}
function point(s){s=((s%total)+total)%total;let i=0;while(lengths[i+1]<s)i++;const a=path[i],b=path[(i+1)%path.length],t=(s-lengths[i])/(lengths[i+1]-lengths[i]);return[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t,Math.atan2(b[1]-a[1],b[0]-a[0])*180/Math.PI]}
function draw(){document.querySelector('#front-spin').setAttribute('transform',`rotate(${angle})`);document.querySelector('#rear-spin').setAttribute('transform',`rotate(${angle*42/rear})`);document.querySelector('#crank-spin').setAttribute('transform',`rotate(${angle})`);links.forEach((el,i)=>{const [x,y,a]=point(i*total/links.length+angle/360*2*Math.PI*46);el.setAttribute('transform',`translate(${x} ${y}) rotate(${a})`)});}
function read(){document.querySelector('#cadence-value').textContent=rpm;document.querySelector('#ratio').innerHTML=(42/rear).toFixed(2)+'<span> : 1</span>';document.querySelector('#wheel').innerHTML=(rpm*42/rear).toFixed(0)+'<span> rpm</span>';document.querySelector('#speed').innerHTML=(rpm*42/rear*2.1*60/1000).toFixed(1)+'<span> km/h</span>'}
function tick(t){const dt=last?Math.min((t-last)/1000,.05):0;last=t;angle=(angle+rpm*6*dt)%360;draw();frame=visible&&!paused&&!reduced.matches?requestAnimationFrame(tick):0}function run(){if(!frame&&visible&&!paused&&!reduced.matches){last=0;frame=requestAnimationFrame(tick)}}
document.querySelector('#cadence').addEventListener('input',e=>{rpm=+e.target.value;read();draw()});document.querySelectorAll('[data-teeth]').forEach(b=>b.addEventListener('click',()=>{rear=+b.dataset.teeth;document.querySelectorAll('[data-teeth]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});document.querySelector('#rear-gear').innerHTML=k.solidSvg(k.extrude(gearRing(76,rear/21*22,rear),44,3,P,{convex:false,bevel:.4}),{tone:'hi'});document.querySelector('#rear-spin').setAttribute('style',`scale:${rear/21};transform-origin:0 0`);route();read();draw()}));document.querySelector('#pause').addEventListener('click',e=>{paused=!paused;e.target.textContent=paused?'Resume motion':'Pause motion';e.target.setAttribute('aria-pressed',paused);run()});new IntersectionObserver(es=>{visible=es.at(-1).isIntersecting;run()}).observe(document.querySelector('#anatomy'));reduced.addEventListener('change',run);route();read();draw();}
if(typeof document!=='undefined')mount();
